CREATE OR REPLACE FUNCTION public.central_lista() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(d ORDER BY d->>'criado_em' DESC),'[]'::jsonb) FROM (SELECT (CASE WHEN public.central_gestor() THEN to_jsonb(r) ELSE to_jsonb(r)-'responsaveis_apurados'-'evidencia_apuracao'-'conclusao' END)||jsonb_build_object('origem',o.nome,'destino',s.nome,'criador',f.nome,'executor',a.nome,'envolvidos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.funcionario_id,'nome',p.nome)) FROM public.reporte_envolvidos e JOIN public.funcionarios p ON p.id=e.funcionario_id WHERE e.reporte_id=r.id AND e.ativo),'[]'::jsonb)) d FROM public.reportes r LEFT JOIN public.funcoes o ON o.id=r.setor_origem_id JOIN public.funcoes s ON s.id=r.setor_destino_id JOIN public.funcionarios f ON f.id=r.reportado_por LEFT JOIN public.funcionarios a ON a.id=r.assumido_por WHERE public.central_ver(r.id)) q; $$;
DROP POLICY IF EXISTS rc_sel_eventos ON public.reporte_eventos; CREATE POLICY rc_sel_eventos ON public.reporte_eventos FOR SELECT TO authenticated USING(public.central_ver(reporte_id) AND (tipo<>'decisao' OR public.central_gestor() OR autor_id=public.rc_meu_funcionario_id()));
CREATE OR REPLACE FUNCTION public.central_auditar_dados() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eu uuid:=public.rc_meu_funcionario_id(); antigo jsonb; novo jsonb; BEGIN IF eu IS NULL THEN RETURN new; END IF; antigo:=jsonb_build_object('executor',old.assumido_por,'prazo',old.prazo_resolucao,'data_prevista',old.data_prevista,'confirmado',old.erro_confirmado,'causa',old.tipo_causa,'conclusao',old.conclusao,'evidencia',old.evidencia_apuracao,'responsaveis',old.responsaveis_apurados,'resultado',old.correcao_resultado,'validacao',old.validacao_evidencia); novo:=jsonb_build_object('executor',new.assumido_por,'prazo',new.prazo_resolucao,'data_prevista',new.data_prevista,'confirmado',new.erro_confirmado,'causa',new.tipo_causa,'conclusao',new.conclusao,'evidencia',new.evidencia_apuracao,'responsaveis',new.responsaveis_apurados,'resultado',new.correcao_resultado,'validacao',new.validacao_evidencia); IF antigo IS DISTINCT FROM novo THEN INSERT INTO public.reporte_eventos(reporte_id,autor_id,tipo,texto) VALUES(new.id,eu,'decisao','Auditoria — anterior: '||antigo::text||' — novo: '||novo::text); END IF; RETURN new; END $$;